def choose_test(kind, groups, paired=False, skewed=False):
    if kind == "share":
        return "proportions_ztest"
    if kind == "category":
        return "chi2_contingency"
    if groups == 1:
        return "ttest_1samp"
    if paired:
        return "ttest_rel"
    if kind == "rank":
        return "mannwhitneyu"
    return "ttest_ind"

choose_test("mean", 2)

